/**
 * Local optomechanics engine vs the Python reference (qgdevs/optomech.py, scipy DOP853 at rtol 1e-10).
 * Fixture generated by the snippet in the comment below with /home/akosa/grqg/.venv/bin/python.
 * Tolerances: the reference is an adaptive integration with rtol 1e-10 / atol 1e-12, while the engine uses the
 * exact matrix exponential, so agreement is limited by the reference's integration error (relative ~1e-7 over
 * thousands of oscillation periods). E_N = −ln 2ν̃₋ involves (Δ − √(Δ² − 4 det V))/2, a difference of nearly
 * equal terms when E_N ≪ 1, so its absolute accuracy is ~1e-10 in ANY implementation: for case 0 at t = T,
 * DOP853 (fixture) gives 1.348776e-6, SciPy's exact expm gives 1.348488e-6 and this engine 1.348549e-6.
 * The reference V carries DOP853 errors ~rtol·|V| (|V| up to e^{2r}/2 for squeezed states) that propagate through
 * the ill-conditioned ν̃₋, so we require 1e-6 relative on E_N where E_N > 1e-3, 2e-8 absolute below, and 1e-6 relative to
 * max|V| on every covariance entry.
 */
import { describe, expect, it } from 'vitest';
import golden from './optomech.golden.json';
import { evolveCoupledOscillators, logNegativityGaussian } from './optomech';

interface Case { params: any; g: number; n_th: number; t: number[]; log_negativity: number[]; V: Record<string, number[][]> }

describe('optomechanics covariance dynamics vs Python reference', () => {
  for (const [ci, c] of (golden as Case[]).entries()) {
    it(`case ${ci} (coupling scale ${c.params.coupling_scale}, max E_N ${Math.max(...c.log_negativity).toExponential(2)})`, () => {
      const r = evolveCoupledOscillators({ ...c.params, n_out: 200 });
      expect(Math.abs(r.coupling_rate_rad_s - c.g) / Math.abs(c.g)).toBeLessThan(1e-12);
      expect(Math.abs(r.thermal_occupation_bath - c.n_th)).toBeLessThanOrEqual(1e-12 * Math.max(1, c.n_th));
      for (let k = 0; k < c.t.length; k++) {
        expect(Math.abs(r.t[k] - c.t[k])).toBeLessThan(1e-9 * Math.max(1, c.t[k]));
        const ref = c.log_negativity[k], got = r.log_negativity[k];
        if (ref > 1e-3) expect(Math.abs(got - ref) / ref).toBeLessThan(1e-6);
        else expect(Math.abs(got - ref)).toBeLessThan(2e-8);
      }
      for (const [i, Vref] of Object.entries(c.V)) {
        const V = r.V[Number(i)];
        const scale = Math.max(...Vref.flat().map(Math.abs));
        for (let a = 0; a < 4; a++) for (let b = 0; b < 4; b++) expect(Math.abs(V[a][b] - Vref[a][b])).toBeLessThan(1e-6 * scale);
      }
    });
  }

  it('vacuum is a separable stationary state without coupling (E_N = 0, V = I/2)', () => {
    const r = evolveCoupledOscillators({ m: 1e-14, d: 1e-4, omega: 6.283, T: 0, gamma: 1e-3, n_init: 0, t_final: 10, coupling_scale: 0, n_out: 20 });
    for (const e of r.log_negativity) expect(e).toBeLessThan(1e-12); // round-off only
    const V = r.V[r.V.length - 1];
    for (let a = 0; a < 4; a++) for (let b = 0; b < 4; b++) expect(Math.abs(V[a][b] - (a === b ? 0.5 : 0))).toBeLessThan(1e-12);
    expect(logNegativityGaussian([[0.5, 0, 0, 0], [0, 0.5, 0, 0], [0, 0, 0.5, 0], [0, 0, 0, 0.5]])).toBe(0);
  });
});
